"""GRPO shape: cr_ambience — Story → Screenplay → KeyFrame → Video → Ambience → AudioMix → Compositor.

50 short-brief samples (target_n=60; remaining 10 go in shape_cr_ambience_long.py).
Cinematic mini-drama WITH ambient atmosphere, NO BGM. Topics span genre/era/protagonist
combinations distinct from SFT shape_cr_ambience.py. Rationale style mirrors SFT
cr_ambience pattern: long flow narrative naming all 7 chain agents + standard reject list.
"""
from __future__ import annotations


_REJECT = (
    "Reject MusicAgent (user asked for atmosphere/ambient bed, not music score), "
    "Transcription/Translation, VideoAnalysis/IntakeVideo/StyleTransfer/VideoExtend/"
    "Highlight, Narration/Illustration/Narrator."
)


def _make(theme, arc, scenes, settings, aesthetic, ambience):
    """Return rationale + intents for one cr_ambience sample (chain length 7)."""
    return {
        "rationale": (
            f"{theme} mini-drama from a text brief + {ambience} ambient bed. "
            f"StoryAgent drafts the {arc} blueprint. ScreenplayAgent breaks it into "
            f"{scenes} scenes. KeyFrameAgent plans keyframes for the {settings} settings "
            "from text alone. VideoAgent assembles the multi-shot film. AmbienceAgent "
            f"generates the {ambience} atmospheric layer. AudioMixAgent layers it under "
            "the dialogue+foley. CompositorAgent muxes the final mp4. " + _REJECT
        ),
        "intents": [
            f"Draft the {theme} story blueprint — {arc} arc.",
            f"Decompose the {arc} arc into {scenes} scenes.",
            f"Plan keyframes for the {settings} settings; text-only generation, no reference images supplied.",
            f"Render per-shot clips preserving {aesthetic} visual continuity.",
            f"Generate the {ambience} ambient atmosphere the user requested as the audio bed.",
            f"Layer the {ambience} ambient bed under the clip's baked dialogue+foley track into one final mixed wav.",
            f"Composite the final {aesthetic} mini-drama mp4 with mixed audio and inter-shot transitions.",
        ],
    }


